-- CLASS_INTEGRATION_STRICT: class:fighter
-- CLASS_PACKAGE_TEST: tests/classTextNarrationAudit.test.ts
-- CLASS_WORK_STATUS: fighter:text=READY;mechanics=NOT_AUDITED
-- CLASS_STATUS_LEDGER: src/rule-templates/CLASS_WORK_STATUS.md
--
-- Production reference delivery hotfix.
-- Presentation only: this migration updates feature labels/descriptions and
-- reference metadata. It MUST NOT change choices, resources, actions, formulas,
-- effects, spell slots, CE dependencies, or any other executable mechanic.

begin;

create or replace function private.fighter_reference_patch_feature(
  p_campaign_id uuid,
  p_catalog_key text,
  p_level integer,
  p_source_key text,
  p_label text,
  p_description text
) returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_template_id uuid;
begin
  select id into v_template_id
  from public.rule_templates
  where campaign_id = p_campaign_id
    and catalog_key = p_catalog_key
    and is_active
  order by version desc
  limit 1;

  if v_template_id is null then
    return;
  end if;

  update public.rule_template_levels l
  set mechanics = coalesce((
    select jsonb_agg(
      case
        when m->>'type' = 'grant'
          and m->>'target' = 'feature'
          and m->>'sourceKey' = p_source_key
        then jsonb_set(
          jsonb_set(m, '{payload,label}', to_jsonb(p_label), true),
          '{payload,description}', to_jsonb(p_description), true
        )
        else m
      end
      order by ord
    )
    from jsonb_array_elements(coalesce(l.mechanics, '[]'::jsonb)) with ordinality q(m, ord)
  ), '[]'::jsonb)
  where l.template_id = v_template_id
    and l.level = p_level;
end;
$$;

create or replace function private.fighter_reference_sync_campaign(p_campaign_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  -- Base Fighter -----------------------------------------------------------
  perform private.fighter_reference_patch_feature(p_campaign_id,'class:fighter',1,'fighting-style','Боевой стиль',$rule$Выберите один талант категории «Боевой стиль», требованиям которого соответствуете, и получите его эффекты постоянно. Каждый раз, когда получаете новый уровень Воина, можете заменить выбранный этим умением Боевой стиль другим подходящим Боевым стилем. Само умение не тратит ресурс; ограничения конкретного стиля указаны в его карточке.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'class:fighter',1,'second-wind','Второе дыхание',$rule$Бонусным действием потратьте 1 использование Второго дыхания и восстановите 1к10 + уровень Воина HP. На 1 уровне запас равен 2 использованиям, на 4 — 3, на 10 — 4. После короткого отдыха возвращается 1 потраченное использование; после долгого отдыха возвращается весь запас.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'class:fighter',1,'weapon-mastery','Мастерство владения оружием',$rule$Выберите 3 вида простого или воинского оружия, которыми владеете: вы можете применять свойство Мастерства каждого выбранного вида оружия. Число выбранных видов становится 4 на 4 уровне Воина, 5 на 10 и 6 на 16. После каждого долгого отдыха можно заменить один выбранный вид оружия другим подходящим видом. Само применение свойства Мастерства не расходует отдельный классовый ресурс, если его собственное правило не говорит обратного.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'class:fighter',2,'action-surge','Всплеск действий',$rule$В свой ход можете потратить 1 использование Всплеска действий и немедленно получить ещё одно действие в этом же ходу. Это дополнительное действие нельзя использовать для действия Магия. До 17 уровня доступно 1 использование, с 17 уровня — 2, но не более одного Всплеска действий за ход. Все использования возвращаются после короткого или долгого отдыха.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'class:fighter',2,'tactical-mind','Тактическое мышление',$rule$Когда вы провалили проверку характеристики, можете потратить применение Второго дыхания не на лечение, а на Тактическое мышление: бросьте 1к10 и прибавьте результат к этой проверке, после чего ГМ заново определяет успех. Если итог всё равно не достигает Сл проверки, применение Второго дыхания по этому правилу не расходуется. Это прямое исключение из обычного правила списания ресурса.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'class:fighter',3,'fighter-subclass','Воинский архетип',$rule$На 3 уровне выберите Воинский архетип. Вы сразу получаете способности 3 уровня выбранного подкласса. На 7, 10, 15 и 18 уровнях Воина тот же архетип даёт следующие способности; повторно выбирать подкласс не нужно, а точные правила каждой способности находятся в его прогрессии.$rule$);

  perform private.fighter_reference_patch_feature(p_campaign_id,'class:fighter',4,'ability-score-improvement','Улучшение характеристик',$rule$Получите талант «Улучшение характеристик» или другой талант по выбору, требованиям которого соответствуете. Если выбран «Улучшение характеристик», увеличьте одну характеристику на 2 либо две характеристики на 1; этим талантом нельзя поднять характеристику выше 20. Воин получает эту возможность на 4, 6, 8, 12, 14 и 16 уровнях.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'class:fighter',5,'extra-attack','Дополнительная атака',$rule$Когда в свой ход совершаете действие Атака, можете выполнить 2 атаки вместо 1. Каждая атака выбирает цель и разрешается отдельно обычным способом. Эта способность пассивна и не расходует ресурс.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'class:fighter',5,'tactical-shift','Тактическое смещение',$rule$Когда бонусным действием активируете Второе дыхание и тратите его использование, в рамках того же бонусного действия можете переместиться на расстояние до половины своей Скорости. Это перемещение не провоцирует атаки по возможности. Дополнительного ресурса сверх уже потраченного Второго дыхания не требуется.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'class:fighter',6,'ability-score-improvement','Улучшение характеристик',$rule$Получите талант «Улучшение характеристик» или другой талант по выбору, требованиям которого соответствуете. Если выбран «Улучшение характеристик», увеличьте одну характеристику на 2 либо две характеристики на 1; этим талантом нельзя поднять характеристику выше 20.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'class:fighter',7,'subclass','Способность Воинского архетипа',$rule$На этом уровне выбранный Воинский архетип даёт способность 7 уровня. Используйте полное правило из прогрессии уже выбранного подкласса; новый архетип не выбирается.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'class:fighter',8,'ability-score-improvement','Улучшение характеристик',$rule$Получите талант «Улучшение характеристик» или другой талант по выбору, требованиям которого соответствуете. Если выбран «Улучшение характеристик», увеличьте одну характеристику на 2 либо две характеристики на 1; этим талантом нельзя поднять характеристику выше 20.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'class:fighter',9,'indomitable','Неукротимый',$rule$После провала спасброска можете потратить 1 использование Неукротимого и перебросить этот спасбросок, добавив к новому результату свой уровень Воина. Новый результат обязателен, даже если он хуже прежнего. Доступно 1 использование на 9 уровне, 2 на 13 и 3 на 17; весь запас возвращается после долгого отдыха.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'class:fighter',9,'tactical-master','Тактический мастер',$rule$Каждый раз, когда совершаете атаку оружием, для которого умеете применять свойство Мастерства, до разрешения эффекта Мастерства можете заменить обычное свойство этого оружия на Push, Sap или Slow только для этой атаки. Бросок атаки и урон не меняются сами по себе; затем применяется выбранное свойство по его собственному правилу. Ресурс не тратится.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'class:fighter',10,'subclass','Способность Воинского архетипа',$rule$На этом уровне выбранный Воинский архетип даёт способность 10 уровня. Используйте полное правило из прогрессии уже выбранного подкласса; новый архетип не выбирается.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'class:fighter',11,'two-extra-attacks','Две дополнительные атаки',$rule$Когда в свой ход совершаете действие Атака, можете выполнить 3 атаки вместо 1. Каждая атака выбирает цель и разрешается отдельно. Эта способность заменяет значение Дополнительной атаки Воина 5 уровня, а не добавляет ещё две атаки поверх него.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'class:fighter',12,'ability-score-improvement','Улучшение характеристик',$rule$Получите талант «Улучшение характеристик» или другой талант по выбору, требованиям которого соответствуете. Если выбран «Улучшение характеристик», увеличьте одну характеристику на 2 либо две характеристики на 1; этим талантом нельзя поднять характеристику выше 20.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'class:fighter',13,'indomitable','Неукротимый',$rule$После провала спасброска можете потратить 1 использование Неукротимого и перебросить этот спасбросок, добавив к новому результату свой уровень Воина. Новый результат обязателен, даже если он хуже прежнего. На 13 уровне доступно 2 использования; весь запас возвращается после долгого отдыха.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'class:fighter',13,'studied-attacks','Изучающие атаки',$rule$Если ваша атака по существу промахнулась, вы получаете преимущество на следующую атаку по этому же существу, совершённую до конца вашего следующего хода. После этой следующей атаки преимущество от способности исчезает независимо от её результата. Ресурс не тратится.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'class:fighter',14,'ability-score-improvement','Улучшение характеристик',$rule$Получите талант «Улучшение характеристик» или другой талант по выбору, требованиям которого соответствуете. Если выбран «Улучшение характеристик», увеличьте одну характеристику на 2 либо две характеристики на 1; этим талантом нельзя поднять характеристику выше 20.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'class:fighter',15,'subclass','Способность Воинского архетипа',$rule$На этом уровне выбранный Воинский архетип даёт способность 15 уровня. Используйте полное правило из прогрессии уже выбранного подкласса; новый архетип не выбирается.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'class:fighter',16,'ability-score-improvement','Улучшение характеристик',$rule$Получите талант «Улучшение характеристик» или другой талант по выбору, требованиям которого соответствуете. Если выбран «Улучшение характеристик», увеличьте одну характеристику на 2 либо две характеристики на 1; этим талантом нельзя поднять характеристику выше 20.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'class:fighter',17,'action-surge','Всплеск действий',$rule$С 17 уровня у вас 2 использования Всплеска действий. В свой ход потратьте 1 использование, чтобы немедленно получить ещё одно действие в этом же ходу; дополнительное действие нельзя использовать для действия Магия. Не более одного Всплеска действий за ход. Все использования возвращаются после короткого или долгого отдыха.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'class:fighter',17,'indomitable','Неукротимый',$rule$После провала спасброска можете потратить 1 использование Неукротимого и перебросить этот спасбросок, добавив к новому результату свой уровень Воина. Новый результат обязателен. На 17 уровне доступно 3 использования; весь запас возвращается после долгого отдыха.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'class:fighter',18,'subclass','Способность Воинского архетипа',$rule$На этом уровне выбранный Воинский архетип даёт способность 18 уровня. Используйте полное правило из прогрессии уже выбранного подкласса; новый архетип не выбирается.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'class:fighter',19,'epic-boon','Эпический дар',$rule$На 19 уровне получите один талант категории «Эпический дар» или другой талант по выбору, требованиям которого соответствуете. Выбранный талант действует по собственному полному описанию и не расходует отдельный классовый ресурс.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'class:fighter',20,'three-extra-attacks','Три дополнительные атаки',$rule$Когда в свой ход совершаете действие Атака, можете выполнить 4 атаки вместо 1. Каждая атака разрешается отдельно. Эта способность заменяет прежнее число атак от Дополнительной атаки, а не складывается с ним.$rule$);

  -- Arcane Archer ---------------------------------------------------------
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:arcane-archer',3,'arcane-archer-l3-1','Магический выстрел',$rule$На 3 уровне выберите 2 варианта Магического выстрела. Один раз за ход, когда выполняется условие выбранного варианта, можно потратить 1 использование Магического выстрела. Всего 2 использования; они полностью возвращаются после короткого или долгого отдыха. Сл спасброска Магического выстрела = 8 + бонус мастерства + модификатор Интеллекта.

Изгоняющая стрела. Когда стрела попадает по существу, оно совершает спасбросок Харизмы. При провале цель изгоняется в безопасное место в Стране Фей: её Скорость становится 0, и она недееспособна до конца своего следующего хода, после чего возвращается. С 18 уровня при попадании дополнительно наносится 2к6 урона силовым полем.

Обманная стрела. При попадании цель получает дополнительно 2к6 психического урона. Выберите союзника в пределах 30 футов от цели: при провале спасброска Мудрости цель очарована им до начала вашего следующего хода; эффект заканчивается раньше, если этот союзник атакует цель, наносит ей урон или заставляет совершить спасбросок. С 18 уровня дополнительный урон 4к6.

Взрывная стрела. Сразу после попадания цель и каждое другое существо в пределах 10 футов от неё получают 2к6 урона силовым полем. Спасброска нет. С 18 уровня урон 4к6.

Ослабляющая стрела. При попадании цель получает дополнительно 2к6 некротического урона и совершает спасбросок Телосложения. При провале урон её атак оружием уменьшается вдвое до начала вашего следующего хода. С 18 уровня дополнительный урон 4к6.

Сжимающая стрела. При попадании цель получает дополнительно 2к6 урона ядом, её Скорость уменьшается на 10 футов, и первый раз за ход, когда она перемещается хотя бы на 1 фут без телепортации, получает 2к6 рубящего урона. Существо в пределах досягаемости может действием снять путы успешной проверкой Силы (Атлетика) против Сл Магического выстрела. Иначе путы держатся 1 минуту или до вашего следующего применения этой опции. С 18 уровня оба вида дополнительного урона 4к6.

Пронзающая стрела. Вместо броска атаки стрела проходит линией шириной 1 фут и длиной 30 футов, проходит сквозь объекты и игнорирует укрытие. Каждое существо в линии совершает спасбросок Ловкости: при провале получает урон как от попадания стрелой + 1к6 колющего, при успехе — половину. С 18 уровня дополнительный колющий урон 2к6.

Ищущая стрела. Вместо броска атаки выберите существо, которое видели за последнюю минуту. Стрела огибает углы и игнорирует половинное и три четверти укрытие, если цель в дальности оружия и существует путь для стрелы. Цель совершает спасбросок Ловкости: при провале получает урон как от попадания + 1к6 силового урона, а вы узнаёте её текущее местоположение; при успехе получает половину и местоположение не раскрывается. С 18 уровня дополнительный урон 2к6.

Теневая стрела. При попадании цель получает дополнительно 2к6 психического урона и совершает спасбросок Мудрости. При провале до начала вашего следующего хода она не видит ничего дальше 5 футов. С 18 уровня дополнительный урон 4к6.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:arcane-archer',7,'magic-arrow-l7-1','Зачарованная стрела',$rule$Немагическая стрела, выпущенная из короткого или длинного лука, считается магической для преодоления сопротивления и иммунитета к немагическим атакам. Способность пассивна и не расходует Магический выстрел.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:arcane-archer',7,'curving-shot-l7-2','Изгибающийся выстрел',$rule$Если магическая стрела промахнулась, бонусным действием можете перенаправить её в другую цель в пределах 60 футов от первоначальной цели и повторить атаку по новой цели. Отдельного ресурса способность не расходует.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:arcane-archer',7,'additional-arcane-shot-option-l7-3','Дополнительный Магический выстрел',$rule$Изучите ещё один вариант Магического выстрела: теперь вы знаете 3 варианта из восьми. Общий запас применений Магического выстрела остаётся равен 2; меняется только число известных вариантов.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:arcane-archer',10,'additional-arcane-shot-option-l10-1','Дополнительный Магический выстрел',$rule$Изучите ещё один вариант Магического выстрела: теперь вы знаете 4 варианта из восьми. Общий запас применений остаётся равен 2.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:arcane-archer',15,'ever-ready-shot-l15-1','Всегда готовый выстрел',$rule$Когда бросаете инициативу и у вас не осталось использований Магического выстрела, немедленно восстановите 1 использование. Это восстановление не требует действия.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:arcane-archer',15,'additional-arcane-shot-option-l15-2','Дополнительный Магический выстрел',$rule$Изучите ещё один вариант Магического выстрела: теперь вы знаете 5 вариантов из восьми. Общий запас применений остаётся равен 2.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:arcane-archer',18,'additional-arcane-shot-option-l18-1','Дополнительный Магический выстрел',$rule$Изучите ещё один вариант Магического выстрела: теперь вы знаете 6 вариантов из восьми. Общий запас применений остаётся равен 2. Дополнительный урон вариантов Магического выстрела меняется на значения, прямо указанные в их правилах 18 уровня.$rule$);

  -- Battle Master ---------------------------------------------------------
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:battle-master',3,'battle-master-l3-1','Боевое превосходство',$rule$На 3 уровне изучите 3 манёвра и получите 4 кости превосходства к8. Манёвр, который требует кость превосходства, расходует 1 кость, если в его тексте не сказано иначе. Все потраченные кости возвращаются после короткого или долгого отдыха. Сл спасброска манёвра = 8 + бонус мастерства + модификатор Силы или Ловкости, на ваш выбор. На 7 уровне вы знаете 5 манёвров и имеете 5 костей; на 10 знаете 7 манёвров, а кость становится к10; на 15 знаете 9 манёвров и имеете 6 костей; на 18 кость становится к12.

Засада. Когда совершаете проверку Ловкости (Скрытность) или бросок инициативы и не Недееспособны, потратьте кость превосходства и добавьте её результат к броску.

Подмена. В свой ход, находясь в пределах 5 футов от согласного существа и имея не менее 5 футов движения, потратьте кость превосходства: поменяйтесь с существом местами, не провоцируя атаки по возможности. Затем выберите одного из вас; выбранный получает бонус к КД, равный результату кости, до начала вашего следующего хода.

Удар командующего. Когда совершаете действие Атака, замените одну свою атаку, потратьте бонусное действие и кость превосходства. Союзник, который видит или слышит вас, может реакцией совершить одну атаку оружием и при попадании добавить результат кости к урону.

Командирский напор. Когда совершаете проверку Харизмы (Запугивание), Харизмы (Выступление) или Харизмы (Убеждение), потратьте кость превосходства и добавьте её результат к проверке.

Обезоруживающая атака. Когда попадаете атакой оружием, потратьте кость превосходства и добавьте её результат к урону. Цель совершает спасбросок Силы; при провале роняет один удерживаемый предмет по вашему выбору к своим ногам.

Отвлекающий удар. Когда попадаете атакой оружием, потратьте кость превосходства и добавьте её результат к урону. Следующая атака другого существа по этой цели до начала вашего следующего хода совершается с преимуществом.

Активное уклонение. Когда начинаете перемещение, потратьте кость превосходства и добавьте её результат к КД до окончания этого перемещения.

Финт. Бонусным действием выберите существо в пределах 5 футов и потратьте кость превосходства. Следующая ваша атака по нему в этом ходу совершается с преимуществом; если она попадает, добавьте результат кости к урону.

Провоцирующая атака. Когда попадаете атакой оружием, потратьте кость превосходства и добавьте её результат к урону. Цель совершает спасбросок Мудрости; при провале до конца вашего следующего хода её атаки по существам, кроме вас, совершаются с помехой.

Выпад. Бонусным действием потратьте кость превосходства и в этот ход совершите действие Атака. До конца хода досягаемость ваших атак ближнего боя увеличивается на 5 футов; к урону одного попадания ближней атакой в рамках этого действия добавьте результат кости.

Маневрирующая атака. Когда попадаете атакой оружием, потратьте кость превосходства и добавьте её результат к урону. Союзник, который видит или слышит вас, может реакцией переместиться на расстояние до половины Скорости, не провоцируя атаку по возможности от поражённой цели.

Угрожающая атака. Когда попадаете атакой оружием, потратьте кость превосходства и добавьте её результат к урону. Цель совершает спасбросок Мудрости; при провале Испугана вами до конца вашего следующего хода.

Парирование. Когда существо наносит вам урон атакой ближнего боя, реакцией потратьте кость превосходства и уменьшите получаемый урон на результат кости + модификатор Ловкости.

Точная атака. Когда промахиваетесь атакой оружием, потратьте кость превосходства и добавьте её результат к броску атаки, после чего заново определите попадание.

Толкающая атака. Когда попадаете атакой оружием, потратьте кость превосходства и добавьте её результат к урону. Если цель Большого размера или меньше, она совершает спасбросок Силы; при провале оттолкните её на расстояние до 15 футов от себя.

Сплочение. Бонусным действием выберите дружественное существо, которое видит или слышит вас, и потратьте кость превосходства. Оно получает временные HP, равные результату кости + модификатор Харизмы.

Ответный удар. Когда существо промахивается по вам атакой ближнего боя, реакцией потратьте кость превосходства и совершите по нему одну атаку оружием ближнего боя. При попадании добавьте результат кости к урону.

Рассекающая атака. Когда попадаете атакой оружием ближнего боя, потратьте кость превосходства и выберите другое существо в пределах 5 футов от первой цели и в вашей досягаемости. Если исходный бросок атаки попал бы и по второй цели, она получает урон, равный результату кости, того же типа, что и исходная атака.

Тактическая оценка. Когда совершаете проверку Интеллекта (Расследование), Интеллекта (История) или Мудрости (Проницательность), потратьте кость превосходства и добавьте её результат к проверке.

Опрокидывающая атака. Когда попадаете атакой оружием, потратьте кость превосходства и добавьте её результат к урону. Если цель Большого размера или меньше, она совершает спасбросок Силы; при провале становится Сбитой с ног.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:battle-master',7,'know-your-enemy-l7-1','Знай своего врага',$rule$Бонусным действием выберите видимое существо в пределах 30 футов. ГМ сообщает его иммунитеты, сопротивления и уязвимости к урону. Одно использование бесплатно и возвращается после долгого отдыха; после расходования бесплатного применения можете без действия потратить 1 кость превосходства, чтобы восстановить это применение.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:battle-master',10,'improved-combat-superiority-l10-1','Улучшенное боевое превосходство',$rule$Ваша кость превосходства становится к10. На этом уровне вы также изучаете ещё 2 манёвра, всего 7 известных. Число костей превосходства остаётся 5; все потраченные кости возвращаются после короткого или долгого отдыха.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:battle-master',15,'relentless-l15-1','Неутомимый',$rule$Один раз за ход, когда используете манёвр, который требует потратить кость превосходства, можете вместо расходования обычной кости бросить бесплатную к8 и использовать её результат как кость превосходства для этого манёвра. На 15 уровне вы также знаете 9 манёвров и имеете 6 обычных костей превосходства.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:battle-master',18,'ultimate-combat-superiority-l18-1','Совершенное боевое превосходство',$rule$Ваша обычная кость превосходства становится к12. Число обычных костей остаётся 6; все потраченные кости возвращаются после короткого или долгого отдыха.$rule$);

  -- Cavalier --------------------------------------------------------------
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:cavalier',3,'cavalier-l3-1','Непоколебимая метка и Рождённый в седле',$rule$Непоколебимая метка. Когда попадаете по существу атакой оружием ближнего боя, можете пометить его до конца вашего следующего хода. Пока помеченная цель находится в пределах 5 футов от вас, её атаки по другим существам совершаются с помехой. Если она нанесла урон кому-то кроме вас, на следующем ходу можете бонусным действием совершить по ней особую атаку оружием ближнего боя с преимуществом; при попадании добавьте урон, равный половине уровня Воина. Число таких особых атак равно вашему модификатору Силы, минимум 1; все использования возвращаются после долгого отдыха.

Рождённый в седле. Вы совершаете с преимуществом спасброски, чтобы не упасть с ездового животного. Если вы в сознании и падаете с него с высоты не более 10 футов, приземляетесь на ноги. Посадка на ездовое животное и спешивание требуют только 5 футов перемещения вместо половины Скорости.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:cavalier',7,'warding-maneuver-l7-1','Защитный манёвр',$rule$Когда вы или существо в пределах 5 футов от вас получает попадание атакой, реакцией бросьте 1к8 и добавьте результат к КД цели против этой атаки. Если после повышения КД атака всё равно попала, цель получает сопротивление урону этой атаки. Число использований равно модификатору Телосложения, минимум 1; все использования возвращаются после долгого отдыха.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:cavalier',10,'hold-the-line-l10-1','Держать строй',$rule$Существо провоцирует вашу атаку по возможности, когда перемещается на 5 футов или больше, оставаясь внутри вашей досягаемости. Если такая атака по возможности попадает, Скорость цели становится 0 до конца текущего хода.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:cavalier',15,'ferocious-charger-l15-1','Свирепый натиск',$rule$Один раз за свой ход, если непосредственно перед попаданием атакой оружием вы переместились не менее чем на 10 футов по прямой к цели, можете заставить цель совершить спасбросок Силы против Сл ваших манёвров. При провале цель становится Сбитой с ног.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:cavalier',18,'vigilant-defender-l18-1','Бдительный защитник',$rule$В бою вы получаете особую реакцию на каждом ходу другого существа. Эту особую реакцию можно использовать только для совершения атаки по возможности. Она не заменяет вашу обычную реакцию и не может быть потрачена на другие способности.$rule$);

  -- Champion --------------------------------------------------------------
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:champion',3,'champion-l3-1','Улучшенный критический и Выдающийся атлет',$rule$Улучшенный критический. Ваши атаки оружием и Безоружные удары наносят критическое попадание при результате 19 или 20 на к20.

Выдающийся атлет. Вы совершаете с преимуществом броски инициативы и проверки Силы (Атлетика). Сразу после того как наносите критическое попадание, можете переместиться на расстояние до половины своей Скорости; это перемещение не провоцирует атаки по возможности.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:champion',7,'additional-fighting-style-l7-1','Дополнительный Боевой стиль',$rule$Получите ещё один талант категории «Боевой стиль», требованиям которого соответствуете. Это отдельный дополнительный Боевой стиль: он не заменяет стиль, полученный от базового Воина, и оба стиля действуют одновременно по собственным правилам. Если правило таланта не разрешает выбирать его повторно, выберите другой подходящий Боевой стиль.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:champion',10,'heroic-warrior-l10-1','Героический воин',$rule$В бою в начале своего хода, если у вас нет Героического вдохновения, вы получаете Героическое вдохновение. Способность не требует действия и не расходует отдельный ресурс подкласса.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:champion',15,'superior-critical-l15-1','Превосходный критический',$rule$Ваши атаки оружием и Безоружные удары теперь наносят критическое попадание при результате 18–20 на к20. Это заменяет диапазон 19–20 от Улучшенного критического, а не складывается с ним.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:champion',18,'survivor-l18-1','Выживший',$rule$Вы совершаете с преимуществом спасброски от смерти, а результат 18–20 на таком спасброске даёт эффект натуральной 20. Кроме того, в начале своего хода, если у вас хотя бы 1 HP и вы Кровоточащий (Bloodied), восстановите HP в количестве 5 + модификатор Телосложения. Лечение не срабатывает при 0 HP.$rule$);

  -- Echo Knight -----------------------------------------------------------
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:echo-knight',3,'echo-knight-l3-1','Проявление эха и Воплощение ярости',$rule$Бонусным действием создайте магическое полупрозрачное эхо в свободном месте, которое видите в пределах 15 футов. У эха КД 14 + ваш бонус мастерства, 1 HP и иммунитет ко всем состояниям; оно использует ваши бонусы спасбросков, занимает своё пространство и уничтожается, если в конце вашего хода находится дальше 30 футов от вас. На своём ходу можете мысленно переместить эхо на расстояние до 30 футов без действия. Когда совершаете действие Атака, каждую свою атаку можете выполнять из собственного пространства или из пространства эха. Бонусным действием можете поменяться с эхом местами: каждый из вас телепортируется в пространство другого, а вы тратите 15 футов своего перемещения. Когда существо в пределах 5 футов от эха перемещается от него хотя бы на 5 футов, можете реакцией совершить по этому существу атаку по возможности так, будто находитесь в пространстве эха.

Воплощение ярости. Когда в свой ход совершаете действие Атака, можете потратить 1 использование этой способности и совершить одну дополнительную атаку оружием ближнего боя из пространства эха. Число использований равно вашему модификатору Телосложения, минимум 1; все потраченные использования возвращаются после долгого отдыха.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:echo-knight',7,'echo-avatar-l7-1','Аватар эха',$rule$Действием перенесите зрение и слух в своё эхо на срок до 10 минут. Пока эффект действует, вы Слепы и Глухи относительно собственных чувств, но видите и слышите через эхо. В этом режиме эхо может удаляться от вас на расстояние до 1000 футов.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:echo-knight',10,'shadow-martyr-l10-1','Теневой мученик',$rule$Когда видимое вами существо становится целью атаки и ваше эхо существует, реакцией до броска атаки переместите эхо в свободное место в пределах 5 футов от цели. Атака вместо исходной цели направляется в эхо. 1 использование; оно возвращается после короткого или долгого отдыха.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:echo-knight',15,'reclaim-potential-l15-1','Возврат потенциала',$rule$Когда ваше эхо уничтожено получением урона и у вас нет временных HP, можете получить временные HP в количестве 2к6 + модификатор Телосложения. Число использований равно модификатору Телосложения, минимум 1; все использования возвращаются после долгого отдыха.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:echo-knight',18,'legion-of-one-l18-1','Легион одного',$rule$Бонусным действием можете создать и одновременно поддерживать два эха. Оба используют правила Проявления эха. Кроме того, когда бросаете инициативу и у вас не осталось использований Воплощения ярости, восстановите 1 использование.$rule$);

  -- Eldritch Knight -------------------------------------------------------
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:eldritch-knight',3,'eldritch-knight-l3-1','Заклинания и Связь с оружием',$rule$Заклинания. Интеллект — ваша заклинательная характеристика. На 3 уровне вы знаете 2 заговора Волшебника; на 10 уровне число заговоров становится 3. На 3 уровне подготовьте 3 заклинания Волшебника 1 уровня. Число подготовленных заклинаний становится 4 на 4 уровне, 5 на 7, 6 на 8, 7 на 10, 8 на 11, 9 на 13, 10 на 14, 11 на 16, 12 на 19 и 13 на 20. Выбирайте заклинания Волшебника тех уровней, которые можете накладывать своими ячейками. Каждый раз, когда получаете уровень Воина, можете заменить одно подготовленное заклинание другим доступным заклинанием Волшебника. Ячейки: на 3 уровне — две 1 уровня; на 4 — три 1 уровня; на 7 — четыре 1 уровня и две 2 уровня; на 10 — четыре 1 уровня и три 2 уровня; на 13 добавляются две 3 уровня; на 16 ячеек 3 уровня становится три; на 19 добавляется одна ячейка 4 уровня. Все ячейки восстанавливаются после долгого отдыха.

Связь с оружием. Проведите 1-часовой ритуал с оружием в пределах досягаемости; ритуал можно провести во время короткого отдыха. Нельзя связать оружие, уже связанное с другим Воином, или магический предмет, настроенный на другое существо. Пока вы не Недееспособны, вас нельзя разоружить связанным оружием. Бонусным действием можете призвать связанное оружие в руку, если оно находится на том же плане существования. Одновременно можно иметь не более двух связанных оружий; связь с третьим прекращает одну из прежних связей по вашему выбору.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:eldritch-knight',7,'war-magic-l7-1','Боевая магия',$rule$Когда в свой ход совершаете действие Атака, можете заменить одну из атак накладыванием одного известного вам заговора Волшебника со временем накладывания «Действие». Остальные атаки этого действия выполняются обычным способом.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:eldritch-knight',10,'eldritch-strike-l10-1','Мистический удар',$rule$Когда попадаете по существу атакой оружием, оно получает помеху на следующий спасбросок против заклинания, которое вы накладываете до конца вашего следующего хода. После соответствующего спасброска эффект для этой цели заканчивается.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:eldritch-knight',15,'arcane-charge-l15-1','Магический рывок',$rule$Когда используете Всплеск действий, можете телепортироваться на расстояние до 30 футов в свободное место, которое видите. Телепортацию можно совершить непосредственно до или после дополнительного действия Всплеска. Отдельного заряда нет: расходуется только Всплеск действий.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:eldritch-knight',18,'improved-war-magic-l18-1','Улучшенная боевая магия',$rule$Когда в свой ход совершаете действие Атака, можете заменить две атаки накладыванием одного подготовленного заклинания Волшебника 1 или 2 уровня со временем накладывания «Действие». Заклинание расходует ячейку обычным способом; остальные атаки действия Атака выполняются отдельно.$rule$);

  -- Psi Warrior -----------------------------------------------------------
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:psi-warrior',3,'psi-warrior-l3-1','Псионическая сила',$rule$Вы получаете запас Костей пси-энергии. На 3 уровне это 4к6; на 5 — 6к8; на 9 — 8 костей; на 11 размер кости становится к10; на 13 — 10 костей; на 17 — 12к12. После короткого отдыха восстановите 1 потраченную Кость пси-энергии; после долгого отдыха восстановите весь запас.

Защитное поле. Реакцией, когда вы или другое видимое вами существо в пределах 30 футов получает урон, потратьте 1 Кость пси-энергии и бросьте её. Уменьшите получаемый урон на результат кости + модификатор Интеллекта, минимум на 1.

Псионический удар. Один раз в каждый свой ход, сразу после того как вы попали по цели в пределах 30 футов атакой оружием и нанесли ей урон, можете потратить 1 Кость пси-энергии. Цель получает дополнительный урон силовым полем, равный результату кости + модификатор Интеллекта.

Телекинетическое передвижение. Магическим действием выберите видимую цель в пределах 30 футов: свободный предмет Большого размера или меньше либо одно согласное существо, кроме вас. Переместите цель на расстояние до 30 футов в свободное видимое место. Если предмет Крошечный, его можно переместить в вашу руку или из руки. Первое применение бесплатно и возвращается после короткого или долгого отдыха; если бесплатное применение потрачено, без действия потратьте 1 Кость пси-энергии, чтобы восстановить его.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:psi-warrior',7,'telekinetic-adept-l7-1','Телекинетический адепт',$rule$Вы получаете две возможности. Усиленный пси-прыжок: бонусным действием получите Скорость полёта, равную удвоенной Скорости ходьбы, до конца текущего хода. Телекинетический толчок: когда наносите урон Псионическим ударом, цель Большого размера или меньше совершает спасбросок Силы против Сл вашей псионики; при провале можете Сбить её с ног либо переместить на 10 футов по горизонтали.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:psi-warrior',10,'guarded-mind-l10-1','Защищённый разум',$rule$Вы получаете сопротивление психическому урону. В начале своего хода, если вы Очарованы или Испуганы, можете потратить 1 Кость пси-энергии и завершить на себе каждый эффект, вызывающий одно из этих состояний.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:psi-warrior',15,'bulwark-of-force-l15-1','Оплот силы',$rule$Бонусным действием выберите существ, включая себя, в пределах 30 футов, числом до модификатора Интеллекта, минимум 1. Каждое выбранное существо получает укрытие наполовину на 1 минуту или пока вы Недееспособны. Одно применение бесплатно и возвращается после долгого отдыха; повторное применение до следующего долгого отдыха требует потратить 1 Кость пси-энергии.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:psi-warrior',18,'telekinetic-master-l18-1','Мастер телекинеза',$rule$Вы можете накладывать «Телекинез» без компонентов; Интеллект — заклинательная характеристика для него. Одно применение бесплатно и возвращается после долгого отдыха; повторное применение до следующего долгого отдыха требует потратить 1 Кость пси-энергии. Пока концентрируетесь на «Телекинезе», бонусным действием можете совершить одну атаку оружием.$rule$);

  -- Banneret --------------------------------------------------------------
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:banneret',3,'banneret-l3-1','Посланник рыцарства и Групповое оздоровление',$rule$Посланник рыцарства даёт три эффекта. Понимание: вы можете накладывать «Понимание языков» только как ритуал; заклинательная характеристика для него — Харизма. Полиглот: вы знаете один дополнительный язык; после долгого отдыха можете заменить его другим языком, который слышали, видели в жестах или читали за последние 24 часа. Поставленная речь: получите владение одним навыком на выбор — Проницательность, Запугивание, Убеждение или Выступление.

Групповое оздоровление. Когда используете Второе дыхание и восстанавливаете себе HP, выберите союзников в 30-футовой эманации числом до модификатора Харизмы, минимум 1. Каждый выбранный союзник восстанавливает 1к4 + уровень Воина HP. 1 использование за короткий или долгий отдых; само Второе дыхание расходуется обычным способом.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:banneret',7,'team-tactics-l7-1','Групповая тактика',$rule$Союзники, которых вы выбрали целью Группового оздоровления, получают преимущество на проверки к20 до начала вашего следующего хода. Эффект применяется одновременно с лечением и не расходует отдельный ресурс.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:banneret',10,'rallying-surge-l10-1','Воодушевляющий всплеск',$rule$Когда используете Всплеск действий, выберите союзников в пределах 30 футов числом до модификатора Харизмы, минимум 1. Каждый выбранный союзник может реакцией либо совершить одну атаку оружием, либо переместиться на расстояние до половины своей Скорости, не провоцируя атаки по возможности. Отдельный ресурс не создаётся: расходуется Всплеск действий.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:banneret',15,'shared-resilience-l15-1','Устойчивость команды',$rule$Когда видимый союзник в пределах 60 футов проваливает спасбросок, реакцией потратьте 1 использование Неукротимого. Союзник перебрасывает спасбросок, добавляет к новому результату ваш уровень Воина и обязан использовать новый результат.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:banneret',18,'inspiring-commander-l18-1','Вдохновляющий командир',$rule$Дальность Группового оздоровления и Воодушевляющего всплеска увеличивается до 60 футов. Союзники в пределах 60 футов от вас имеют иммунитет к состояниям Очарованный и Испуганный, пока вы не Недееспособны.$rule$);

  -- Rune Knight -----------------------------------------------------------
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:rune-knight',3,'rune-knight-l3-1','Мощь великана и Рунный резчик',$rule$Мощь великана. Бонусным действием на 1 минуту, если вы меньше Большого размера, становитесь Большим вместе со всем надетым; получаете преимущество на проверки Силы и спасброски Силы; один раз на каждом своём ходу при попадании атакой оружием или Безоружным ударом наносите дополнительно 1к6 урона. Число использований равно бонусу мастерства; весь запас возвращается после долгого отдыха.

Рунный резчик. После долгого отдыха нанесите каждую известную руну на отдельное оружие, броню, щит, украшение или другой предмет, который носите или держите. Чтобы пользоваться пассивным и активным эффектом руны, нужно носить или держать предмет с ней. На 3 уровне вы знаете 2 руны, на 7 — 3, на 10 — 4, на 15 — 5. Холмовая и Штормовая руны доступны только с 7 уровня. Каждая руна имеет собственные использования; до 15 уровня её активируемая сила восстанавливается после короткого или долгого отдыха, а с Мастером рун каждую известную руну можно активировать дважды между отдыхами.

Облачная руна. Пассивно проверки Ловкости (Ловкость рук) и Харизмы (Обман) совершаются с преимуществом. Когда вы или видимое существо в пределах 30 футов получает попадание атакой, реакцией активируйте руну и выберите другое существо в пределах 30 футов от себя: выбранное существо становится новой целью той же атаки с тем же броском атаки.

Огненная руна. Пассивно бонус мастерства удваивается для проверок характеристик с инструментом, которым вы владеете. После попадания атакой оружием активируйте руну: цель получает дополнительно 2к6 огненного урона и совершает спасбросок Силы. При провале она Опутана огненными оковами на 1 минуту, получает 2к6 огненного урона в начале каждого своего хода и повторяет спасбросок в конце каждого своего хода, завершая эффект при успехе.

Ледяная руна. Пассивно проверки Мудрости (Уход за животными) и Харизмы (Запугивание) совершаются с преимуществом. Бонусным действием активируйте руну на 10 минут: получаете +2 ко всем проверкам и спасброскам Силы и Телосложения.

Каменная руна. Пассивно проверки Мудрости (Проницательность) совершаются с преимуществом, и вы получаете тёмное зрение на 120 футов. Когда видимое существо заканчивает ход в пределах 30 футов, реакцией активируйте руну: цель совершает спасбросок Мудрости. При провале она Очарована вами, Недееспособна и имеет Скорость 0 на 1 минуту; в конце каждого своего хода повторяет спасбросок и завершает эффект при успехе.

Холмовая руна, с 7 уровня. Пассивно вы совершаете с преимуществом спасброски против яда и получаете сопротивление урону ядом. Бонусным действием активируйте руну на 1 минуту: получаете сопротивление дробящему, колющему и рубящему урону.

Штормовая руна, с 7 уровня. Пассивно проверки Интеллекта (Магия) совершаются с преимуществом, и вас нельзя застать врасплох, пока вы не Недееспособны. Бонусным действием активируйте руну на 1 минуту. Пока она активна, когда вы или видимое существо в пределах 60 футов совершает бросок атаки, спасбросок или проверку характеристики, можете реакцией дать этому броску преимущество или помеху.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:rune-knight',7,'runic-shield-l7-1','Рунный щит',$rule$Когда другое видимое вами существо в пределах 60 футов получает попадание атакой, реакцией заставьте атакующего перебросить к20 и использовать новый результат. Число использований равно вашему бонусу мастерства; все использования возвращаются после долгого отдыха.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:rune-knight',7,'additional-rune-known-l7-2','Дополнительная руна',$rule$Изучите ещё одну руну: теперь вы знаете 3. С этого уровня становятся доступны Холмовая и Штормовая руны. Каждая выбранная руна сохраняет собственный пассивный эффект и собственные активации.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:rune-knight',10,'great-stature-l10-1','Великий рост',$rule$Ваш рост увеличивается на 3к4 дюйма. Дополнительный урон от Мощи великана становится 1к8 вместо 1к6. Остальные условия и число использований Мощи великана не меняются.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:rune-knight',10,'additional-rune-known-l10-2','Дополнительная руна',$rule$Изучите ещё одну руну: теперь вы знаете 4. Выберите её из доступных рун, соблюдая требования по уровню.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:rune-knight',15,'master-of-runes-l15-1','Мастер рун',$rule$Каждую известную вам руну теперь можно активировать дважды между отдыхами вместо одного раза. После короткого или долгого отдыха восстанавливаются оба использования каждой руны. Руны по-прежнему являются отдельными способностями и не образуют общий запас.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:rune-knight',15,'additional-rune-known-l15-2','Дополнительная руна',$rule$Изучите ещё одну руну: теперь вы знаете 5. Выберите её из доступных рун, соблюдая требования по уровню.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:rune-knight',18,'runic-juggernaut-l18-1','Рунный исполин',$rule$Когда активируете Мощь великана, можете стать Огромного размера вместо Большого. Пока Мощь великана активна, ваша досягаемость увеличивается на 5 футов, а её дополнительный урон становится 1к10. Запас и длительность Мощи великана не меняются.$rule$);

  -- Samurai ---------------------------------------------------------------
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:samurai',3,'samurai-l3-1','Боевой дух',$rule$Бонусным действием получите преимущество на все атаки оружием до конца текущего хода и 5 временных HP. На 10 уровне временных HP становится 10, на 15 — 15. У вас 3 использования Боевого духа; все возвращаются после долгого отдыха.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:samurai',7,'elegant-courtier-l7-1','Элегантный придворный',$rule$Добавляйте модификатор Мудрости к проверкам Харизмы (Убеждение). Также получаете владение спасбросками Мудрости; если уже владеете ими, получите владение спасбросками Интеллекта или Харизмы на выбор.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:samurai',10,'tireless-spirit-l10-1','Неутомимая душа',$rule$Когда бросаете инициативу и у вас не осталось использований Боевого духа, немедленно восстановите 1 использование. Это восстановление не требует действия.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:samurai',15,'rapid-strike-l15-1','Стремительный удар',$rule$Один раз за свой ход, если атака оружием совершается с преимуществом, можете отказаться от преимущества этой атаки и вместо этого сделать ещё одну атаку оружием по той же цели в рамках того же действия.$rule$);
  perform private.fighter_reference_patch_feature(p_campaign_id,'subclass:fighter:samurai',18,'strength-before-death-l18-1','Стойкость перед смертью',$rule$Если урон опускает ваши HP до 0, но не убивает мгновенно, реакцией задержите потерю сознания и немедленно совершите дополнительный ход, прервав текущий. Пока длится этот дополнительный ход, вы имеете 0 HP и не теряете сознание; получение урона вызывает провалы спасбросков от смерти как обычно, а три провала могут убить вас. Когда дополнительный ход заканчивается, вы теряете сознание, если всё ещё имеете 0 HP. 1 использование за долгий отдых.$rule$);

  -- Reference-facing template summaries. No executable mechanics change.
  update public.rule_templates
  set mechanical_summary = case catalog_key
      when 'class:fighter' then 'Воин — мастер оружия и темпа боя: Второе дыхание, Всплеск действий, Мастерство оружия, Неукротимый и растущее число атак.'
      when 'subclass:fighter:arcane-archer' then 'Мистический лучник превращает попадания из лука в восемь конкретных вариантов Магического выстрела с собственными целями, спасбросками и эффектами.'
      when 'subclass:fighter:battle-master' then 'Мастер боя расходует кости превосходства на выбранные манёвры; каждый манёвр имеет собственный триггер, цель и результат.'
      when 'subclass:fighter:cavalier' then 'Кавалер удерживает врагов рядом, защищает союзников реакциями и наказывает перемещение и атаки по другим целям.'
      when 'subclass:fighter:champion' then 'Чемпион усиливает критические попадания, атлетизм, Боевые стили и выживаемость без отдельного сложного ресурса.'
      when 'subclass:fighter:echo-knight' then 'Рыцарь эха создаёт боевое эхо, атакует и реагирует из его позиции, меняется с ним местами и развивает контроль двух позиций.'
      when 'subclass:fighter:eldritch-knight' then 'Мистический рыцарь сочетает прогрессию Воина с заклинаниями Волшебника, связью с оружием и заменой отдельных атак магией.'
      when 'subclass:fighter:psi-warrior' then 'Пси-воин расходует Кости пси-энергии на защиту, дополнительный урон и телекинез, постепенно увеличивая запас и размер кости.'
      when 'subclass:fighter:banneret' then 'Баннерет превращает базовые ресурсы Воина в поддержку группы: лечение, реакции союзников и совместную устойчивость.'
      when 'subclass:fighter:rune-knight' then 'Рунный рыцарь сочетает Мощь великана с выбранными рунами; каждая руна имеет собственный пассивный и активируемый эффект.'
      when 'subclass:fighter:samurai' then 'Самурай тратит Боевой дух на преимущество и временные HP, а на высоких уровнях превращает преимущество и стойкость в дополнительные атаки и ход.'
      else mechanical_summary
    end,
    rules_meta = coalesce(rules_meta, '{}'::jsonb)
      || jsonb_build_object(
        'class_work_status', jsonb_build_object('text','READY','mechanics','NOT_AUDITED'),
        'reference_delivery','SYNCED_2026_08_29'
      ),
    updated_at = now()
  where campaign_id = p_campaign_id
    and is_active
    and (catalog_key = 'class:fighter' or catalog_key like 'subclass:fighter:%');
end;
$$;

do $$
declare r record;
begin
  for r in select id from public.campaigns loop
    perform private.fighter_reference_sync_campaign(r.id);
  end loop;
end;
$$;

commit;
